import openpyxl

wb = openpyxl.load_workbook('/workspace/task/output.xlsx')
ws = wb['Sheet1']

for r in range(4, 17):
    serial = ws.cell(r, 2).value
    weight = ws.cell(r, 4).value
    # count occurrences of serial up to and including this row
    count = 0
    for rr in range(4, r+1):
        if ws.cell(rr, 2).value == serial:
            count += 1
    if count == 1:
        ws.cell(r, 5).value = 0
    else:
        # find previous row with same serial
        prev_weight = None
        for rr in range(r-1, 3, -1):
            if ws.cell(rr, 2).value == serial:
                prev_weight = ws.cell(rr, 4).value
                break
        ws.cell(r, 5).value = weight - prev_weight

wb.save('/workspace/task/output.xlsx')
print("done")

